(function(){document.querySelectorAll(".bb-next-days__list").forEach((list)=>{const lang=list.dataset.lang||document.documentElement.lang||"en";const say=(text)=>{list.innerHTML="";const item=document.createElement("li");item.className="bb-next-days__note";item.textContent=text;list.appendChild(item);};const day=(iso,options)=>{const[y,m,d]=iso.split("-").map(Number);return new Intl.DateTimeFormat(lang,options).format(new Date(y,m-1,d));};say(list.dataset.loading);const url=new URL(list.dataset.source,window.location.href);url.searchParams.set("instructor",list.dataset.instructor);url.searchParams.set("count",list.dataset.count);fetch(url,{credentials:"same-origin"}).then((response)=>(response.ok?response.json():Promise.reject(response.status))).then((data)=>{const days=(data&&data.days)||[];if(!days.length){say(list.dataset.empty);return;}
list.innerHTML="";days.forEach((entry)=>{const row=document.createElement("li");row.className="bb-next-days__day";const when=document.createElement("span");when.className="bb-next-days__date";const weekday=document.createElement("span");weekday.textContent=day(entry.date,{weekday:"short"});when.append(weekday," "+day(entry.date,{day:"numeric"})+" "+day(entry.date,{month:"short"}),);row.appendChild(when);const times=document.createElement("span");times.className="bb-next-days__times";const minutes=(clock)=>{const[h,m]=String(clock).split(":").map(Number);return h*60+(m||0);};const slots=[];entry.lessons.forEach((lesson)=>{lesson.times.forEach((range)=>{const[start,end]=String(range).split(/[–-]/);slots.push({lesson,start,length:minutes(end)-minutes(start)});});});slots.sort((a,b)=>a.length-b.length||minutes(a.start)-minutes(b.start));slots.forEach(({lesson,start})=>{const link=document.createElement("a");const target=new URL(list.dataset.booking,window.location.href);target.searchParams.set("bb_lesson",lesson.id);target.searchParams.set("bb_date",entry.date);link.href=target.toString();link.className="bb-next-days__time";link.setAttribute("aria-label",list.dataset.bookLabel.replace("%1$s",lesson.name).replace("%2$s",start).replace("%3$s",day(entry.date,{weekday:"long",day:"numeric",month:"long"}),),);const name=document.createElement("span");name.textContent=lesson.name;const time=document.createElement("strong");time.textContent=start;link.append(name,time);times.appendChild(link);});row.appendChild(times);list.appendChild(row);});}).catch(()=>say(list.dataset.empty));});})();